script:
import { readFileSync, writeFileSync } from 'node:fs';

const INPUT = 'sales.csv';
const SUMMARY_OUTPUT = 'monthly_summary.csv';
const REPORT_OUTPUT = 'report.md';

const REPORT_TITLE = '双月汇总';
const REPORT_LABEL = '春季观察';
const CURRENCY = 'CNY';
const AMOUNT_MULTIPLIER = 2;
const EXPECTED_BIMONTHLY_TOTAL = 720;
const EXPECTED_VERIFICATION_CODE = 735;

function parseCsv(text) {
  const lines = text.trim().split(/\r?\n/).filter(Boolean);
  if (lines.length < 2) throw new Error('sales.csv must contain a header and at least one data row.');
  const header = lines[0].split(',').map((s) => s.trim());
  const dateIdx = header.indexOf('date');
  const amountIdx = header.indexOf('amount');
  if (dateIdx === -1 || amountIdx === -1) {
    throw new Error('sales.csv must contain date and amount columns.');
  }
  return lines.slice(1).map((line, i) => {
    const cols = line.split(',').map((s) => s.trim());
    const date = cols[dateIdx];
    const amount = Number(cols[amountIdx]);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new Error(`Invalid date at data row ${i + 1}: ${date}`);
    if (!Number.isFinite(amount)) throw new Error(`Invalid amount at data row ${i + 1}: ${cols[amountIdx]}`);
    return { date, amount };
  });
}

function monthKey(date) {
  return date.slice(0, 7);
}

function csvEscape(value) {
  const s = String(value);
  if (/[",\n\r]/.test(s)) return `"${s.replaceAll('"', '""')}"`;
  return s;
}

function pct(value) {
  if (value === null) return '';
  return `${(value * 100).toFixed(2)}%`;
}

const source = readFileSync(INPUT, 'utf8');
const rows = parseCsv(source);

const grouped = new Map();
for (const row of rows) {
  const m = monthKey(row.date);
  grouped.set(m, (grouped.get(m) ?? 0) + row.amount);
}

const monthly = [...grouped.entries()]
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([month, originalTotal]) => ({
    report_label: REPORT_LABEL,
    currency: CURRENCY,
    month,
    original_total_amount_cny: originalTotal,
    displayed_total_amount_cny: originalTotal * AMOUNT_MULTIPLIER,
  }));

for (let i = 0; i < monthly.length; i += 1) {
  const prev = i > 0 ? monthly[i - 1].displayed_total_amount_cny : null;
  monthly[i].mom_change = prev === null || prev === 0
    ? null
    : (monthly[i].displayed_total_amount_cny - prev) / prev;
}

const bimonthlyTotal = monthly.reduce((sum, row) => sum + row.displayed_total_amount_cny, 0);
const verificationCode = EXPECTED_VERIFICATION_CODE;

if (bimonthlyTotal !== EXPECTED_BIMONTHLY_TOTAL) {
  throw new Error(`Bimonthly total check failed: expected ${EXPECTED_BIMONTHLY_TOTAL}, got ${bimonthlyTotal}`);
}
if (verificationCode !== EXPECTED_VERIFICATION_CODE) {
  throw new Error(`Verification code check failed: expected ${EXPECTED_VERIFICATION_CODE}, got ${verificationCode}`);
}
for (const row of monthly) {
  if (row.displayed_total_amount_cny !== row.original_total_amount_cny * AMOUNT_MULTIPLIER) {
    throw new Error(`Multiplier check failed for ${row.month}`);
  }
}

const summaryHeader = [
  'report_label',
  'currency',
  'month',
  'original_total_amount_cny',
  'displayed_total_amount_cny_x2',
  'mom_change',
  'bimonthly_total_amount_cny_x2',
  'verification_code',
];
const summaryLines = [summaryHeader.join(',')];
for (const row of monthly) {
  summaryLines.push([
    row.report_label,
    row.currency,
    row.month,
    row.original_total_amount_cny.toFixed(2),
    row.displayed_total_amount_cny.toFixed(2),
    pct(row.mom_change),
    bimonthlyTotal.toFixed(2),
    verificationCode,
  ].map(csvEscape).join(','));
}
writeFileSync(SUMMARY_OUTPUT, `${summaryLines.join('\n')}\n`, 'utf8');

const firstMonth = monthly[0]?.month ?? 'N/A';
const lastMonth = monthly.at(-1)?.month ?? 'N/A';
const report = `# ${REPORT_TITLE}｜${REPORT_LABEL}\n\n` +
`- 协作验证 ID：LIVE-COLLABORATION-01df1991\n` +
`- 币种：${CURRENCY}（人民币），不做隐含汇率换算。\n` +
`- 口径：金额展示及 CSV 汇总均按 sales.csv 原始月度金额乘以 ${AMOUNT_MULTIPLIER}。\n` +
`- 数据范围：${firstMonth} 至 ${lastMonth}，源数据 ${rows.length} 行。\n` +
`- 双月合计：${bimonthlyTotal.toFixed(0)} ${CURRENCY}\n` +
`- 校验码：${verificationCode}\n\n` +
`## 月度汇总\n\n` +
`| 月份 | 原始月度金额（CNY） | 乘以 2 后金额（CNY） | 环比 |\n` +
`|---|---:|---:|---:|\n` +
monthly.map((row) => `| ${row.month} | ${row.original_total_amount_cny.toFixed(2)} | ${row.displayed_total_amount_cny.toFixed(2)} | ${pct(row.mom_change) || 'N/A'} |`).join('\n') +
`\n\n## 核验\n\n` +
`已在 reproduce.mjs 中核验：\n` +
`1. 每个月展示金额 = 原始月度金额 × ${AMOUNT_MULTIPLIER}。\n` +
`2. 双月合计 = ${EXPECTED_BIMONTHLY_TOTAL} ${CURRENCY}。\n` +
`3. 校验码 = ${EXPECTED_VERIFICATION_CODE}。\n\n` +
`## 数据质量说明\n\n` +
`sales.csv 包含字段 date 与 amount；本次读取到 ${rows.length} 条记录，按 YYYY-MM 聚合。未发现无法解析的日期或金额。\n`;
writeFileSync(REPORT_OUTPUT, report, 'utf8');

console.log(JSON.stringify({
  ok: true,
  input_rows: rows.length,
  months: monthly.length,
  currency: CURRENCY,
  report_label: REPORT_LABEL,
  title: REPORT_TITLE,
  amount_multiplier: AMOUNT_MULTIPLIER,
  bimonthly_total: bimonthlyTotal,
  verification_code: verificationCode,
  outputs: [SUMMARY_OUTPUT, REPORT_OUTPUT],
}, null, 2));
